import pytest


def age_at(born: int, now: int) -> int:
    """Whole years elapsed between birth year `born` and year `now`.

    Only years are compared; the clock is never read.
    Returns now - born (0 when born == now).
    Raises ValueError if now < born.
    """
    if now < born:
        raise ValueError("now must not be earlier than born")
    return now - born


def test_typical_age() -> None:
    assert age_at(1990, 2025) == 35


def test_same_year_is_zero() -> None:
    assert age_at(2000, 2000) == 0


def test_one_year() -> None:
    assert age_at(2023, 2024) == 1


def test_century_span() -> None:
    assert age_at(1900, 2000) == 100


def test_result_is_int() -> None:
    assert isinstance(age_at(1980, 2020), int)


def test_born_in_future_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2030, 2025)


def test_born_one_year_after_now_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)


def test_non_positive_years() -> None:
    assert age_at(-100, 50) == 150
    assert age_at(0, 0) == 0

